export const AUCTION_ITEM_BY_ID = new Map(AUCTION_ITEMS.map(item => [item.id, item]))

export const AUCTION_RARITIES = Object.freeze({
  LEGENDARY: { icon: '👑', stars: '★★★★★☆☆' },
  MYTHIC: { icon: '🌌', stars: '★★★★★★☆' },
  SECRET: { icon: '🔮', stars: '★★★★★★★' }
})
const AUCTION_RARITY_ORDER = Object.keys(AUCTION_RARITIES)
const AUCTION_ITEMS_BY_PRICE = [...AUCTION_ITEMS].sort((first, second) =>
  Number(first.price) - Number(second.price)
)

export function getAuctionItemRarity(item) {
  if (!AUCTION_ITEMS_BY_PRICE.length) return null
  const price = Number(item?.price)
  const priceRank = AUCTION_ITEMS_BY_PRICE.findIndex(entry => Number(entry.price) >= price)
  const rank = priceRank < 0 ? AUCTION_ITEMS_BY_PRICE.length - 1 : priceRank
  const rarityIndex = Math.min(
    AUCTION_RARITY_ORDER.length - 1,
    Math.floor(rank * AUCTION_RARITY_ORDER.length / AUCTION_ITEMS_BY_PRICE.length)
  )
  const name = AUCTION_RARITY_ORDER[rarityIndex]
  return { name, ...AUCTION_RARITIES[name] }
}

